// xxhash32: xxHash32 (seed 0) of 8 MiB of generated bytes.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define P1 0x9E3779B1u
#define P2 0x85EBCA77u
#define P3 0xC2B2AE3Du

static uint32_t rotl(uint32_t x, int r) { return x << r | x >> (32 - r); }
static uint32_t round_(uint32_t acc, uint32_t w) { return rotl(acc + w * P2, 13) * P1; }
static uint32_t word(const uint8_t *p) { uint32_t w; memcpy(&w, p, 4); return w; }

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    uint32_t v1 = P1 + P2, v2 = P2, v3 = 0, v4 = 0 - P1;
    for (int64_t p = 0; p < n; p += 16) {
        v1 = round_(v1, word(data + p));
        v2 = round_(v2, word(data + p + 4));
        v3 = round_(v3, word(data + p + 8));
        v4 = round_(v4, word(data + p + 12));
    }
    uint32_t h = rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18) + (uint32_t)n;
    h = (h ^ h >> 15) * P2;
    h = (h ^ h >> 13) * P3;
    h ^= h >> 16;
    printf("%u\n", h);
    free(data);
    return 0;
}
